-- =====================================================================
-- MySQL database for the escape room game: two tables, Users and Hints.
-- Run with:  mysql -u root -p < database.sql
-- =====================================================================

USE game_database;

-- ---------------------------------------------------------------------
-- Users
-- user_id is the PRIMARY KEY and is generated by MySQL (AUTO_INCREMENT).
-- password stores a hash produced by the application, never plain text.
-- There is no email column.
-- ---------------------------------------------------------------------
CREATE TABLE Users (
    user_id INT AUTO_INCREMENT PRIMARY KEY,
    username VARCHAR(50) NOT NULL,
    password VARCHAR(255) NOT NULL,
    room_id INT,
    connection_status VARCHAR(20) DEFAULT 'Disconnected',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

-- ---------------------------------------------------------------------
-- Hints
-- hint_id is the PRIMARY KEY and is generated by MySQL (AUTO_INCREMENT).
-- user_id is a FOREIGN KEY -> Users.user_id (one user, many hints).
-- ---------------------------------------------------------------------
CREATE TABLE Hints (
    hint_id INT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NOT NULL,
    room_id INT,
    hint_text TEXT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,

    FOREIGN KEY (user_id)
        REFERENCES Users(user_id)
);

-- ---------------------------------------------------------------------
-- Sample records (IDs are generated automatically: 1, 2, 3, 4, 5)
-- ---------------------------------------------------------------------
