-- ---------------------------------------------------------------------
-- Verification
-- ---------------------------------------------------------------------
SHOW TABLES;
DESCRIBE Users;
DESCRIBE Hints;

-- Shows Hints.user_id -> Users.user_id
SELECT TABLE_NAME, COLUMN_NAME, REFERENCED_TABLE_NAME, REFERENCED_COLUMN_NAME
FROM information_schema.KEY_COLUMN_USAGE
WHERE TABLE_SCHEMA = 'game_database' AND REFERENCED_TABLE_NAME IS NOT NULL;
